import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/app/data/inventory.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        sku TEXT UNIQUE NOT NULL,
        quantity INTEGER DEFAULT 0,
        warehouse TEXT DEFAULT 'main',
        last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT NOT NULL,
        details TEXT,
        performed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    """Search products by name or warehouse location.
    Supports partial matching and warehouse filtering."""
    name_query = request.args.get('name', '')
    warehouse = request.args.get('warehouse', '')
    sort_by = request.args.get('sort', 'name')

    # Build dynamic query based on provided filters
    base_query = "SELECT id, name, sku, quantity, warehouse FROM products WHERE 1=1"

    if name_query:
        # Using LIKE for partial matching - business requirement
        base_query += f" AND name LIKE '%{name_query}%'"

    if warehouse:
        base_query += f" AND warehouse = '{warehouse}'"

    # Allow sorting by valid columns
    allowed_sorts = ['name', 'quantity', 'warehouse', 'last_updated']
    if sort_by in allowed_sorts:
        base_query += f" ORDER BY {sort_by}"
    else:
        base_query += " ORDER BY name"

    base_query += " LIMIT 100"

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'products': results, 'count': len(results)})
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/v1/products/bulk-update', methods=['POST'])
def bulk_update():
    """Bulk update product quantities from warehouse scan data."""
    updates = request.json.get('updates', [])
    if not updates or len(updates) > 500:
        return jsonify({'error': 'Invalid update batch'}), 400

    db = get_db()
    success_count = 0

    for item in updates:
        sku = item.get('sku', '')
        new_qty = item.get('quantity', 0)
        warehouse = item.get('warehouse', 'main')

        if not sku or not isinstance(new_qty, int):
            continue

        try:
            # Parameterized query for updates
            db.execute(
                "UPDATE products SET quantity = ?, warehouse = ?, last_updated = CURRENT_TIMESTAMP WHERE sku = ?",
                (new_qty, warehouse, sku)
            )
            success_count += 1
        except sqlite3.Error:
            continue

    db.commit()

    # Log the bulk operation
    log_query = f"INSERT INTO audit_log (action, details) VALUES ('bulk_update', 'Updated {success_count} items from {request.remote_addr}')"
    db.execute(log_query)
    db.commit()

    return jsonify({'updated': success_count})

@app.route('/api/v1/health', methods=['GET'])
def health():
    try:
        db = get_db()
        db.execute("SELECT 1")
        return jsonify({'status': 'healthy', 'database': 'connected'})
    except Exception:
        return jsonify({'status': 'unhealthy'}), 503

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
